style.css:
@-moz-document url-prefix("https://track.pf.mts.ru/browse") {
.mts-data-table {
        table-layout: fixed !important;
        width: 100% !important;
    }

    .mts-data-table tr > * {
        overflow: hidden;
    }

    .mts-data-table tr > *:nth-child(1) {
        width: calc(34%) !important;
    }

    .mts-data-table tr > *:nth-child(2) {
        width: calc(8%) !important;
    }

    .mts-data-table tr > *:nth-child(3) {
    		width: calc(6.8%) !important;
    }

    .mts-data-table tr > *:nth-child(4) {
        width: calc(3%) !important;
    }

    .mts-data-table tr > *:nth-child(5) {
        width: calc(2.5%) !important;
    }

    .mts-data-table tr > *:nth-child(6) {
        width: calc(12%) !important;
    }

    .mts-data-table tr > *:nth-child(7) {
        width: calc(4%) !important;
    }
}
